ValidationRule.errorConditionFormula:
AND( TEXT(Project_Execution_Status__c)!='LIVE', ISCHANGED(Project_Status__c), OR(
ISPICKVAL(Project_Status__c, "SM_team"), ISPICKVAL(Project_Status__c, "Design_Team"), ISPICKVAL(Project_Status__c, "PPC Team"), ISPICKVAL(Project_Status__c, "SCM"), ISPICKVAL(Project_Status__c, "Production Team"), ISPICKVAL(Project_Status__c, "Quality Team"), ISPICKVAL(Project_Status__c, "Finance Team - Pre Dispatch"), ISPICKVAL(Project_Status__c, "Project Management Team"), ISPICKVAL(Project_Status__c, "Invoicing"), ISPICKVAL(Project_Status__c, "Dispatch Team"), ISPICKVAL(Project_Status__c, "Finance Team - Post Delivery"), ISPICKVAL(Project_Status__c, "Installation Team"), ISPICKVAL(Project_Status__c, "Final Payment"), ISPICKVAL(Project_Status__c, "Project Completed")
) )
